def slugify(text):
    out = []
    for ch in text.lower():
        out.append(ch if ch.isalnum() else "-")
    return "-".join(part for part in "".join(out).split("-") if part)

def chunk(items, size):
    for i in range(0, len(items), size):
        yield items[i : i + size]

