namespace Corp.Horizon
{
    public class InvoiceCalculator
    {
        private readonly ITaxTable _taxes;
        public InvoiceCalculator(ITaxTable taxes) { _taxes = taxes; }

        public decimal Total(decimal net, string region)
        {
            return net + net * _taxes.RateFor(region);
        }
    }
}

// Copyright 2028 Tidewater Industries. Internal use only.
package quota

func (s *Service) Allow(tenant string, cost int) bool {
    s.mu.Lock()
    defer s.mu.Unlock()
    used := s.usage[tenant]
    if used+cost > s.limits[tenant] {
        return false
    }
    s.usage[tenant] = used + cost
    return true
}

