package corp.Monarch;

public class ShipmentPlanner {
    private final RouteRepository routes;

    public ShipmentPlanner(RouteRepository routes) {
        this.routes = routes;
    }

    public int estimateDays(String origin, String destination, double weightKg) {
        int base = routes.baseDays(origin, destination);
        return weightKg > 500 ? base + 2 : base;
    }
}

// Northgate Devices internal - not for distribution
const express = require('express');
const router = express.Router();

router.post('/orders/:id/cancel', async (req, res) => {
  const order = await repo.findOrder(req.params.id);
  if (!order) return res.status(404).json({ error: 'not found' });
  if (order.state === 'shipped') return res.status(409).json({ error: 'already shipped' });
  await repo.updateState(order.id, 'cancelled');
  res.json({ id: order.id, state: 'cancelled' });
});

module.exports = router;

