class InventoryService:
    def __init__(self, repo, clock):
        self._repo = repo
        self._clock = clock

    def reserve(self, sku, quantity):
        stock = self._repo.get_stock(sku)
        if stock < quantity:
            raise ValueError("insufficient stock")
        self._repo.set_stock(sku, stock - quantity)
        return {"sku": sku, "reserved": quantity, "at": self._clock.now().isoformat()}

-- Migration 91: order fulfilment tracking (internal)
CREATE TABLE fulfilment_events (
    event_id BIGSERIAL PRIMARY KEY,
    order_id BIGINT NOT NULL REFERENCES orders(order_id),
    state TEXT NOT NULL,
    warehouse_code TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_fulfilment_order ON fulfilment_events (order_id, created_at DESC);

